entries[225240] = { ["name"] = "PH_1", ["text"] = "Binds when picked up\nUnique\nRequires level 75 to 78 ( 78)" }
entries[225241] = { ["name"] = "Refurbished Tinker: Alarm-O-Turret", ["text"] = "Tinker Module\nUnique-Equipped: Alarm-O-Turret (1)\nRefurbished Alarm-O-Turret\nEquip: Insert into a Tinker Socket for the following effect:\n\nAlarm-O-Turret\nPlace a hidden Alarm-O-Turret on a nearby targeted location. If an enemy player enters its detection radius, it will alert you of their presence and attempt to defend the area for 30 sec or until destroyed.\n\"Refurbished for use in Khaz Algar equipment. Success chance is equivalent to a mid-quality Algari tinker.\"\nSell Price:" }
entries[225242] = { ["name"] = "Refurbished Tinker: Plane Displacer", ["text"] = "Tinker Module\nUnique-Equipped: Plane Displacer (1)\nRefurbished Plane Displacer\nEquip: Insert into a Tinker Socket for the following effect:\n\nPlane Displacer\nGrants the user invisibility for 14-18 sec.\n\"Refurbished for use in Khaz Algar equipment. Success chance is equivalent to a mid-quality Algari tinker.\"\nSell Price:" }
entries[225243] = { ["name"] = "Refurbished Tinker: Supercollide-O-Tron", ["text"] = "Tinker Module\nUnique-Equipped: Supercollide-O-Tron (1)\nRefurbished Supercollide-O-Tron\nEquip: Insert into a Tinker Socket for the following effect:\n\nSupercollide-O-Tron\nLock on to a distant enemy target, up to 12 to 60 yds away. After 1.5 sec, if your path remains unobstructed, you will charge toward them at the speed of sound. Both you and your target will be stunned for 1.5 sec upon collision.\nRequires Dragon Isles Engineering (1)\n\"Refurbished for use in Khaz Algar equipment. Success chance is equivalent to a mid-quality Algari tinker.\"\nSell Price:" }
entries[225244] = { ["name"] = "Refurbished Tinker: Shadowflame Rockets", ["text"] = "Tinker Module\nUnique-Equipped: Shadowflame Rockets (1)\nRefurbished Shadowflame Rockets\nEquip: Insert into a Tinker Socket for the following effect:\n\nShadowflame Rockets\nHop onto a plank of wood with a haphazard shadowflame rocket attachment. Absolutely nothing could go wrong, but if it did, deal 31949 Shadowflame damage split between you and enemies caught in the theoretical blast.\n\"Refurbished for use in Khaz Algar equipment. Success chance is equivalent to a mid-quality Algari tinker.\"\nSell Price:" }
