entries[225250] = { ["name"] = "Startouched Furline", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses the Startouched Furline.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"An early eternal traveler encountered the furline and befriended a pair. Accompanying the traveler back to their domain, these furline kittens were forever changed by living there and accompanying the travelers.\"\nIn-Game Shop" }
