entries[225554] = { ["name"] = "Sunless Lure", ["text"] = "Binds when picked up\nUnique\nUse: Squish together a Sunless Lure, Murkfin Lure, Hungering Shimmerfin, and a Ragefin Necrostaff. Should be fine.\n\"You pulled this from the head of an Illusion projecting kobyss in the Sunless Strand. With enough examples, you may be able to give them a taste of their own medicine.\"\nSell Price:" }
entries[225555] = { ["name"] = "Periapt of Pure Flame", ["text"] = "Quest Item\nUse: Apply a perfume to enhance your spells and weapons with holy fire. (3s cooldown) (30 Sec Cooldown)\n\"Molded in Beledar's image.\"" }
entries[225556] = { ["name"] = "Ancient Construct", ["text"] = "Binds when picked up\nToy\nUse: Summon Icarus the Unbreakable at target location for 1 min. This acts as a target dummy that can be damaged and healed by opposing roles while it persists. How far up will you make the numbers go?\n\nOnly usable outdoors. (1 Hour Cooldown)" }
entries[225557] = { ["name"] = "Sizzling Cinderpollen", ["text"] = "Binds to Warband\n\"Causes particularly painful sneezing fits. The meadery might have a use for it.\"\nSell Price:" }
entries[225558] = { ["name"] = "Murkfin Lure", ["text"] = "Binds when picked up\nUnique\nUse: Squish together a Sunless Lure, Murkfin Lure, Hungering Shimmerfin, and a Ragefin Necrostaff. Should be fine.\n\"You took this from a kobyss trying to fool you in the Velhan's Claim. With enough parts, you may be able to turn the tables.\"\nSell Price:" }
entries[225559] = { ["name"] = "Hungering Shimmerfin", ["text"] = "Binds when picked up\nUnique\nUse: Squish together a Sunless Lure, Murkfin Lure, Hungering Shimmerfin, and a Ragefin Necrostaff. Should be fine.\n\"You took this shimmering scale from a kobyss trying to distract you with an illusion in the Hungering Pool.\"\nSell Price:" }
entries[225560] = { ["name"] = "Ragefin Necrostaff", ["text"] = "Binds when picked up\nUnique (5)\nUse: Squish together a Sunless Lure, Murkfin Lure, Hungering Shimmerfin, and a Ragefin Necrostaff. Should be fine.\n\"Taken from the Ragefin necromages. This thrums with power. Perhaps it could be used to turn the tables on the kobyss.\"\nSell Price:" }
